stdout=from __future__ import annotations

import math
from itertools import combinations
from typing import Any

Atom = tuple[str, float, float, float]


def parse_xyz(path: str) -> list[Atom]:
    with open(path, "r", encoding="utf-8") as handle:
        lines = [line.strip() for line in handle if line.strip()]
    try:
        natoms = int(lines[0].split()[0])
        atom_lines = lines[2 : 2 + natoms]
    except Exception:
        atom_lines = lines
    atoms: list[Atom] = []
    for line in atom_lines:
        parts = line.split()
        if len(parts) >= 4:
            try:
                atoms.append((parts[0], float(parts[1]), float(parts[2]), float(parts[3])))
            except ValueError:
                pass
    return atoms


def _dist(a: Atom, b: Atom) -> float:
    return math.sqrt((a[1] - b[1]) ** 2 + (a[2] - b[2]) ** 2 + (a[3] - b[3]) ** 2)


def _vec(a: Atom, b: Atom) -> tuple[float, float, float]:
    return (a[1] - b[1], a[2] - b[2], a[3] - b[3])


def _dot(u: tuple[float, float, float], v: tuple[float, float, float]) -> float:
    return sum(x * y for x, y in zip(u, v))


def _norm(u: tuple[float, float, float]) -> float:
    return math.sqrt(max(_dot(u, u), 0.0))


def _angle(a: Atom, center: Atom, b: Atom) -> float | None:
    u, v = _vec(a, center), _vec(b, center)
    den = _norm(u) * _norm(v)
    if den == 0:
        return None
    c = max(-1.0, min(1.0, _dot(u, v) / den))
    return math.degrees(math.acos(c))


def _find_atoms(atoms: list[Atom], symbol: str) -> list[Atom]:
    return [a for a in atoms if a[0].lower() == symbol.lower()]


def _safe_float(value: Any) -> float | None:
    try:
        out = float(value)
    except Exception:
        return None
    return out if math.isfinite(out) else None


def extract_electronic_values(result_dump: dict) -> dict[str, float | None]:
    text_keys = {"homo_energy", "somo_energy", "co_charge", "co_spin_density"}
    found: dict[str, float | None] = {k: None for k in text_keys}

    def walk(obj: Any, trail: str = "") -> None:
        if isinstance(obj, dict):
            for key, val in obj.items():
                low = str(key).lower()
                next_trail = f"{trail}.{low}"
                if found["homo_energy"] is None and ("homo" in low or "somo" in low) and "energy" in low:
                    found["homo_energy"] = _safe_float(val)
                if found["co_charge"] is None and "charge" in low and ("co" in low or "cobalt" in next_trail):
                    found["co_charge"] = _safe_float(val)
                if found["co_spin_density"] is None and "spin" in low and ("co" in low or "cobalt" in next_trail):
                    found["co_spin_density"] = _safe_float(val)
                walk(val, next_trail)
        elif isinstance(obj, list):
            for val in obj:
                walk(val, trail)

    walk(result_dump)
    return found


def geometry_descriptors(atoms: list[Atom]) -> dict:
    cobalt = _find_atoms(atoms, "Co")
    ps = _find_atoms(atoms, "P")
    os = _find_atoms(atoms, "O")
    heavy = [a for a in atoms if a[0].upper() != "H"]
    out: dict[str, Any] = {"atom_count": len(atoms)}
    if not cobalt:
        out.update({"valid_geometry": False, "reason": "no cobalt atom found"})
        return out
    co = cobalt[0]
    p_dists = sorted([_dist(co, p) for p in ps])[:2]
    o_dists = sorted([_dist(co, o) for o in os])[:2]
    bound_ps = [d for d in p_dists if 1.9 <= d <= 2.7]
    bound_os = [d for d in o_dists if 1.7 <= d <= 2.4]
    bite_angle = _angle(ps[0], co, ps[1]) if len(ps) >= 2 else None
    coord_atoms = []
    if len(ps) >= 2:
        coord_atoms.extend(sorted(ps, key=lambda a: _dist(co, a))[:2])
    if len(os) >= 2:
        coord_atoms.extend(sorted(os, key=lambda a: _dist(co, a))[:2])
    angles = [_angle(a, co, b) for a, b in combinations(coord_atoms, 2)]
    angles = [a for a in angles if a is not None]
    square_planar_distortion = min(
        1.0,
        sum(min(abs(a - 90.0), abs(a - 180.0)) for a in angles) / max(len(angles) * 45.0, 1.0),
    ) if angles else 1.0
    nonbonded = []
    for a, b in combinations(heavy, 2):
        d = _dist(a, b)
        if d > 0.1:
            nonbonded.append(d)
    min_heavy_distance = min(nonbonded) if nonbonded else None
    crowd_atoms = [a for a in heavy if a[0] not in {"Co", "P", "O"} and _dist(co, a) <= 3.5]
    crowding_score = len(crowd_atoms) + (0.0 if min_heavy_distance is None else max(0.0, 1.2 - min_heavy_distance) * 5.0)
    valid = len(bound_ps) >= 2 and len(bound_os) >= 2 and (min_heavy_distance is None or min_heavy_distance >= 0.65)
    out.update(
        {
            "valid_geometry": valid,
            "co_p_distances": p_dists,
            "co_o_distances": o_dists,
            "both_phosphines_coordinated": len(bound_ps) >= 2,
            "acac_coordinated": len(bound_os) >= 2,
            "co_p_asymmetry": abs(p_dists[0] - p_dists[1]) if len(p_dists) >= 2 else 9.9,
            "p_co_p_bite_angle": bite_angle,
            "square_planar_distortion": square_planar_distortion,
            "heavy_atoms_near_co_3p5A": len(crowd_atoms),
            "min_heavy_heavy_distance": min_heavy_distance,
            "steric_crowding_raw": crowding_score,
            "ligand_remains_bound": len(bound_ps) >= 2,
            "severe_collapse": min_heavy_distance is not None and min_heavy_distance < 0.65,
        }
    )
    return out


def objective_scores(validity: dict, geom: dict, electronic: dict) -> dict[str, float]:
    feasible = bool(validity.get("scf_converged") and validity.get("optimization_success") and geom.get("valid_geometry"))
    if not feasible:
        return {
            "electronic_activation": -100.0,
            "coordination_stability": -100.0,
            "chelate_geometry": -100.0,
            "steric_crowding": 100.0,
        }
    homo = electronic.get("homo_energy")
    charge = electronic.get("co_charge")
    spin = electronic.get("co_spin_density")
    homo_score = 0.0 if homo is None else max(-5.0, min(5.0, (homo + 0.20) * 20.0))
    charge_score = 0.0 if charge is None else max(-3.0, min(3.0, -charge))
    spin_score = 0.0 if spin is None else max(-3.0, 3.0 - abs(spin - 1.0) * 3.0)
    p_asym = float(geom.get("co_p_asymmetry") or 9.9)
    stability = 10.0 - 10.0 * min(1.0, p_asym / 0.4)
    bite = geom.get("p_co_p_bite_angle")
    bite_penalty = 10.0 if bite is None else min(10.0, abs(float(bite) - 92.0) / 4.0)
    distortion = float(geom.get("square_planar_distortion") or 1.0)
    chelate = 10.0 - bite_penalty - 5.0 * distortion
    crowd = float(geom.get("steric_crowding_raw") or 0.0)
    return {
        "electronic_activation": float(homo_score + charge_score + spin_score),
        "coordination_stability": float(stability),
        "chelate_geometry": float(chelate),
        "steric_crowding": float(crowd),
    }

def _validity_from_result(result_dump: dict) -> dict:
    text = json.dumps(result_dump).lower()
    total_energy = result_dump.get("total_energy") if isinstance(result_dump, dict) else None
    if total_energy is None and isinstance(result_dump, list) and result_dump:
        total_energy = result_dump[0].get("energy") if isinstance(result_dump[0], dict) else None
    return {
        "scf_converged": "converged': false" not in text and '"converged": false' not in text and total_energy is not None,
        "optimization_success": "geometryoptimisation" in text or "geometry optimization" in text or total_energy is not None,
        "total_energy": total_energy,
    }


def mock_evaluate(candidate: Candidate, artifacts_dir: Path) -> dict:
    artifacts_dir.mkdir(parents=True, exist_ok=True)
    steric_map = {"Me": 0.0, "Et": 0.3, "iPr": 0.6, "Cy": 0.9, "Ph": 0.7, "p-Tol": 0.8, "p-Anisyl": 0.85, "p-CF3-Ph": 1.0}
    elec_map = {"Me": 0.0, "Et": 0.05, "iPr": 0.08, "Cy": 0.04, "Ph": -0.05, "p-Tol": -0.02, "p-Anisyl": -0.12, "p-CF3-Ph": 0.18}
    linker_geom = {"ethylene": 8.0, "propylene": 6.5, "1,2-phenylene": 7.0, "cis-1,2-cyclohexylene": 7.5}
    crowd = steric_map[candidate.r1] + steric_map[candidate.r2]
    asym = abs(steric_map[candidate.r1] - steric_map[candidate.r2])
    objectives = {
        "electronic_activation": 1.0 + elec_map[candidate.r1] + elec_map[candidate.r2] - 0.1 * crowd,
        "coordination_stability": 8.0 - 2.0 * asym - 0.3 * crowd,
        "chelate_geometry": linker_geom[candidate.linker] - asym,
        "steric_crowding": crowd,
    }
    record = {
        "candidate": candidate.asdict(),
        "mode": "mock",
        "validity": {"scf_converged": True, "optimization_success": True},
        "descriptors": {"mock_note": "deterministic smoke-test surrogate; no chemistry calculations run"},
        "objectives": objectives,
        "feasible": True,
    }
    (artifacts_dir / f"{candidate.candidate_id}_mock_result.json").write_text(json.dumps(record, indent=2), encoding="utf-8")
    return record


def evaluate_candidate(
    candidate: Candidate,
    artifacts_dir: Path,
    *,
    mock: bool,
    charge: int,
    spin_multiplicity: int,
    basis_set: str,
    xc_functional: str,
    geometry_max_steps: int,
    workflow_timeout_s: float | None,
) -> dict:
    if mock:
        return mock_evaluate(candidate, artifacts_dir)
    candidate_dir = artifacts_dir / candidate.candidate_id
    candidate_dir.mkdir(parents=True, exist_ok=True)
    try:
        xyz_path = build_complex_with_estructural(candidate, artifacts_dir)
        result_dump, captured = run_geometry_optimization(
            xyz_path,
            charge=charge,
            spin_multiplicity=spin_multiplicity,
            basis_set=basis_set,
            xc_functional=xc_functional,
            geometry_max_steps=geometry_max_steps,
            workflow_timeout_s=workflow_timeout_s,
        )
        if captured.strip():
            (candidate_dir / "pyscf_console.txt").write_text(captured, encoding="utf-8")
        atoms = _atoms_from_pyscf_result(result_dump) or parse_xyz(xyz_path.as_posix())
        geom = geometry_descriptors(atoms)
        electronic = extract_electronic_values(result_dump if isinstance(result_dump, dict) else {"result": result_dump})
        validity = _validity_from_result(result_dump)
        objectives = objective_scores(validity, geom, electronic)
        feasible = all(v > -99.0 for k, v in objectives.items() if k != "steric_crowding") and objectives["steric_crowding"] < 99.0
        record = {
            "candidate": candidate.asdict(),
            "mode": "pyscf",
            "assumptions": {
                "complex_charge": charge,
                "spin_multiplicity": spin_multiplicity,
                "basis_set": basis_set,
                "xc_functional": xc_functional,
                "geometry_max_steps": geometry_max_steps,
            },
            "xyz_path": xyz_path.as_posix(),
            "validity": validity,
            "geometry_descriptors": geom,
            "electronic_descriptors": electronic,
            "objectives": objectives,
            "feasible": feasible,
            "pyscf_result": result_dump,
        }
    except Exception as exc:
        logfire.info("candidate_evaluation_failed", candidate_id=candidate.candidate_id, error=str(exc))
        if _is_infrastructure_error(exc):
            record = {
                "candidate": candidate.asdict(),
                "mode": "infrastructure_failed",
                "validity": {"scf_converged": False, "optimization_success": False, "error": str(exc)},
                "feasible": False,
            }
            (candidate_dir / "infrastructure_failure.json").write_text(json.dumps(_jsonable(record), indent=2), encoding="utf-8")
            raise InfrastructureEvaluationError(str(exc)) from exc
        record = {
            "candidate": candidate.asdict(),
            "mode": "failed",
            "validity": {"scf_converged": False, "optimization_success": False, "error": str(exc)},
            "objectives": {
                "electronic_activation": -100.0,
                "coordination_stability": -100.0,
                "chelate_geometry": -100.0,
                "steric_crowding": 100.0,
            },
            "feasible": False,
        }
    (candidate_dir / "evaluation.json").write_text(json.dumps(_jsonable(record), indent=2), encoding="utf-8")
    return record
