pts=[('eth__Me__Me',[-0.08263508031848854,9.989296189252297,8.51758501228108,-9.0]),('eth__Et__Et',[0.16914626730929117,9.756678857986092,8.394435445172117,-8.0]),('eth__iPr__iPr',[0.19177037191740576,9.605045916719781,8.606335928605834,-10.0])]
